/**
 * The FULL Piper voice list (every voice for any language), so users can pick
 * any voice for their target language and have it downloaded on demand, beyond
 * the small curated default set in {@link ./catalog.ts}.
 *
 * It reads the voice catalog (`voices/catalog/piper.json`, generated by
 * scripts/gen-voice-catalog.mjs from rhasspy/piper-voices at a PINNED commit).
 * The previous snapshot pointed every download at `resolve/main` with no
 * checksum, so an upstream change or a truncated proxy response installed
 * whatever arrived. Now each URL names the commit and each file carries the
 * sha256 and size the installer checks before a voice counts as installed.
 */
import type { PiperVoiceInfo, VoiceEntry } from '@videodubber/shared';
import { allCatalogVoices, baseLanguage, findCatalogVoice } from '../voices/voiceCatalog.js';

const QUALITY_RANK: Record<string, number> = { high: 4, medium: 3, low: 2, x_low: 1 };

function piperEntries(): VoiceEntry[] {
  return allCatalogVoices().filter((v) => v.engine === 'piper');
}

/** "vi-VN" -> "Vietnamese", in English, for the legacy label. */
function englishLanguageName(tag: string): string {
  try {
    return new Intl.DisplayNames(['en'], { type: 'language' }).of(tag) ?? tag;
  } catch {
    return tag;
  }
}

function entryToVoiceInfo(e: VoiceEntry): PiperVoiceInfo {
  const onnx = e.files.find((f) => f.destPath.endsWith('.onnx'));
  const config = e.files.find((f) => f.destPath.endsWith('.onnx.json'));
  const language = e.languages[0] ?? '';
  const speakerCount = e.speakers?.length ?? 1;
  const speakers = speakerCount > 1 ? ` · ${speakerCount} speakers` : '';
  return {
    id: e.id,
    language,
    label: `${englishLanguageName(language)} — ${e.name} (${e.quality ?? 'medium'})${speakers}`,
    approxSizeMb: Math.round(e.sizeMb),
    url: onnx?.url ?? '',
    configUrl: config?.url ?? '',
    ...(e.quality ? { quality: e.quality } : {}),
    numSpeakers: speakerCount,
    languageCode: language.replace('-', '_'),
    ...(onnx ? { sha256: onnx.sha256, bytes: onnx.bytes } : {}),
    ...(config ? { configSha256: config.sha256, configBytes: config.bytes } : {}),
  };
}

/** Resolve any Piper voice id (a model, not a "#speaker" id) from the catalog. */
export function resolvePiperVoice(voiceId: string): PiperVoiceInfo | undefined {
  const e = findCatalogVoice(voiceId);
  return e?.engine === 'piper' && e.id === voiceId ? entryToVoiceInfo(e) : undefined;
}

/**
 * Every Piper voice for a target language (matched on the base subtag), sorted
 * best-first: higher quality, then single-speaker, then id. Empty if Piper has
 * no voice for the language (the worker then uses system/fallback TTS).
 */
export function listVoicesForLanguage(language: string): PiperVoiceInfo[] {
  const base = baseLanguage(language);
  if (!base) return [];
  return piperEntries()
    .filter((e) => e.languages.some((l) => baseLanguage(l) === base))
    .map(entryToVoiceInfo)
    .sort(
      (a, b) =>
        (QUALITY_RANK[b.quality ?? ''] ?? 0) - (QUALITY_RANK[a.quality ?? ''] ?? 0) ||
        (a.numSpeakers ?? 1) - (b.numSpeakers ?? 1) ||
        a.id.localeCompare(b.id),
    );
}

/** Catalog size (for diagnostics/tests). */
export function voiceCatalogStats(): { voices: number; languages: number } {
  const entries = piperEntries();
  return {
    voices: entries.length,
    languages: new Set(entries.flatMap((e) => e.languages.map(baseLanguage))).size,
  };
}
